def validate_topics(topics, exam_name):
    print(f"Validating {len(topics)} topics for {exam_name}...")
    assert len(topics) == 100, f"Expected exactly 100 topics for {exam_name}, got {len(topics)}"
    seen_titles = set()
    for idx, (title, subject, system, hallmark, ref_label, ref_url) in enumerate(topics):
        assert title not in seen_titles, f"Duplicate title '{title}' in {exam_name} at index {idx}"
        seen_titles.add(title)
        assert subject in TAXONOMY_SUBJECTS, f"Invalid subject '{subject}' in {exam_name} at index {idx}"
        assert system in TAXONOMY_SYSTEMS, f"Invalid system '{system}' in {exam_name} at index {idx}"
        assert len(title) <= 80, f"Title > 80 chars '{title}' in {exam_name} at index {idx}"
        assert len(hallmark) >= 20, f"Hallmark too short in {exam_name} at index {idx}"
        assert ref_url.startswith("https://"), f"Invalid ref_url '{ref_url}' in {exam_name} at index {idx}"
    print(f"  All 100 topics for {exam_name} validated successfully!")

if __name__ == "__main__":
    validate_topics(UHS_MBBS_RAW, "UHS MBBS")
    validate_topics(PLAB_RAW, "PLAB / UKMLA")
    validate_topics(AMC_RAW, "AMC")
    
    out_path = os.path.join(os.path.dirname(__file__), "mega83_topics_b.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Generated Mega-Batch 83 Topics (Part B)\n")
        f.write(f"UHS_MBBS_TOPICS = {json.dumps(UHS_MBBS_RAW, indent=2)}\n\n")
        f.write(f"PLAB_TOPICS = {json.dumps(PLAB_RAW, indent=2)}\n\n")
        f.write(f"AMC_TOPICS = {json.dumps(AMC_RAW, indent=2)}\n")
    print(f"Successfully wrote {out_path}!")
